// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count total Friday the 13ths in a full 400-year cycle.

// --- Earliest Friday the 13th starting from 0001-01-01 ---
DateTime earliest = DateTime.MinValue;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            if (earliest == DateTime.MinValue)
            {
                earliest = d;
                Console.WriteLine($"Earliest Friday the 13th: {d:yyyy-MM-dd}");
            }
        }
    }
    if (earliest != DateTime.MinValue && year == 1)
        break; // found one in year 1, no need to keep scanning for "earliest"
}

// If not found in year 1, the loop above already continued
if (earliest == DateTime.MinValue)
    Console.WriteLine("No Friday the 13th found (unexpected!)");

// --- Count in a full 400-year cycle (years 1–400) ---
int count = 0;
var monthCounts = new Dictionary<int, int>();
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            monthCounts[month] = monthCounts.GetValueOrDefault(month) + 1;
        }
    }
}

Console.WriteLine($"\nFriday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F3}");

Console.WriteLine("\nBreakdown by month:");
foreach (var (month, mc) in monthCounts.OrderBy(kv => kv.Key))
    Console.WriteLine($"  {new DateTime(1, month, 1):MMMM,-12} {mc}");

